{"category_edits":[{"category":"embedding_representation","rationale":"Allow the exclusive mask token to learn its input magnitude while keeping real-item embeddings tied and normalized at radius 0.75. Apply across all four datasets. The generated predictor imports this same model class, so training and inference remain consistent without checkpoint shape changes.","edits":[{"find":"    def effective_item_weight(self) -> torch.Tensor:
        row_norm = 0.75 * math.sqrt(2.0 * self.hidden_units / (self.itemnum + 2 + self.hidden_units))
        nonpadding = torch.nn.functional.normalize(
            self.item_emb.weight[1:], p=2, dim=-1, eps=1e-12
        ) * row_norm
        return torch.cat((torch.zeros_like(self.item_emb.weight[:1]), nonpadding), dim=0)","replace":"    def effective_item_weight(self) -> torch.Tensor:
        row_norm = 0.75 * math.sqrt(2.0 * self.hidden_units / (self.itemnum + 2 + self.hidden_units))
        real_items = torch.nn.functional.normalize(
            self.item_emb.weight[1:self.mask_token], p=2, dim=-1, eps=1e-12
        ) * row_norm
        mask_vector = self.item_emb.weight[self.mask_token:self.mask_token + 1]
        return torch.cat(
            (torch.zeros_like(self.item_emb.weight[:1]), real_items, mask_vector), dim=0
        )"}]}],"change_summary":"Exempt only the exclusive mask-token embedding from normalization; preserve real-item radius 0.75, tying, frequency modulation, backbone, scoring, loss, optimizer and category routing."}
